#include <WiFi.h>
#include <WebServer.h>

const char* ssid = "ESP32_PWM";
const char* password = "pwm12345";

const int PWM_PIN = 25;

WebServer server(80);

uint32_t pwmFreq = 1000;
bool pwmEnabled = true;
uint8_t pwmBits = 10;

const char page[] PROGMEM = R"HTML(
<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>ESP32 PWM Generator</title>
<style>
body {
  font-family: Arial, sans-serif;
    background: #101827;
      color: white;
        text-align: center;
          padding: 20px;
            max-width: 520px;
              margin: auto;
              }
              .panel {
                background: #1d2a3e;
                  padding: 22px;
                    border-radius: 18px;
                    }
                    h1 { color: #55d6be; }
                    #freq {
                      font-size: 30px;
                        font-weight: bold;
                          color: #55d6be;
                            margin: 20px 0;
                              overflow-wrap: anywhere;
                              }
                              input[type=range] {
                                width: 100%;
                                  margin: 20px 0;
                                  }
                                  input[type=number] {
                                    width: 85%;
                                      box-sizing: border-box;
                                        padding: 12px;
                                          font-size: 18px;
                                            border-radius: 8px;
                                              border: 0;
                                                text-align: center;
                                                }
                                                button {
                                                  padding: 13px 20px;
                                                    margin: 8px;
                                                      border: 0;
                                                        border-radius: 10px;
                                                          font-size: 17px;
                                                            background: #55d6be;
                                                              color: #10202b;
                                                              }
                                                              small { color: #b8c6d9; }
                                                              </style>
                                                              </head>
                                                              <body>
                                                              <div class="panel">
                                                                <h1>⚡ ESP32 PWM</h1>

                                                                  <p>Текущая частота:</p>
                                                                    <div id="freq">1000 Hz</div>

                                                                      <input id="slider" type="range"
                                                                               min="0" max="1000" value="428">

                                                                                 <p>Введи частоту вручную:</p>
                                                                                   <input id="number" type="number"
                                                                                            min="1" max="10000000" value="1000">

                                                                                              <p>Диапазон: 1–10000000 Hz</p>

                                                                                                <button onclick="sendFreq()">Установить частоту</button>
                                                                                                  <br>
                                                                                                    <button onclick="power(1)">ВКЛ</button>
                                                                                                      <button onclick="power(0)">ВЫКЛ</button>

                                                                                                        <p id="status">Готово</p>
                                                                                                          <small>Выход PWM: GPIO 25</small>
                                                                                                          </div>

                                                                                                          <script>
                                                                                                          const slider = document.getElementById('slider');
                                                                                                          const number = document.getElementById('number');
                                                                                                          const label = document.getElementById('freq');
                                                                                                          const statusText = document.getElementById('status');

                                                                                                          function fmt(f) {
                                                                                                            return Math.round(f) + ' Hz';
                                                                                                            }

                                                                                                            function sliderFreq() {
                                                                                                              return Math.max(1, Math.round(
                                                                                                                  Math.pow(10, Number(slider.value) / 1000 * 7)
                                                                                                                    ));
                                                                                                                    }

                                                                                                                    function updateLabel(f) {
                                                                                                                      label.textContent = fmt(f);
                                                                                                                        number.value = f;
                                                                                                                        }

                                                                                                                        slider.addEventListener('input', () => {
                                                                                                                          updateLabel(sliderFreq());
                                                                                                                          });

                                                                                                                          number.addEventListener('input', () => {
                                                                                                                            const f = Number(number.value);
                                                                                                                              if (Number.isFinite(f) && f >= 1 && f <= 10000000) {
                                                                                                                                  slider.value = Math.round(Math.log10(f) / 7 * 1000);
                                                                                                                                      label.textContent = fmt(f);
                                                                                                                                        }
                                                                                                                                        });

                                                                                                                                        async function sendFreq() {
                                                                                                                                          const f = Math.round(Number(number.value));

                                                                                                                                            if (!Number.isFinite(f) || f < 1 || f > 10000000) {
                                                                                                                                                statusText.textContent = 'Введи частоту от 1 до 10000000 Hz';
                                                                                                                                                    return;
                                                                                                                                                      }

                                                                                                                                                        try {
                                                                                                                                                            const response = await fetch('/set?freq=' + f);
                                                                                                                                                                statusText.textContent = response.ok
                                                                                                                                                                      ? 'Установлено: ' + fmt(f)
                                                                                                                                                                            : 'Ошибка установки частоты';
                                                                                                                                                                              } catch (e) {
                                                                                                                                                                                  statusText.textContent = 'Нет связи с ESP32';
                                                                                                                                                                                    }
                                                                                                                                                                                    }

                                                                                                                                                                                    async function power(on) {
                                                                                                                                                                                      try {
                                                                                                                                                                                          const response = await fetch('/power?on=' + on);
                                                                                                                                                                                              statusText.textContent = response.ok
                                                                                                                                                                                                    ? (on ? 'PWM включён' : 'PWM выключен')
                                                                                                                                                                                                          : 'Ошибка';
                                                                                                                                                                                                            } catch (e) {
                                                                                                                                                                                                                statusText.textContent = 'Нет связи с ESP32';
                                                                                                                                                                                                                  }
                                                                                                                                                                                                                  }
                                                                                                                                                                                                                  </script>
                                                                                                                                                                                                                  </body>
                                                                                                                                                                                                                  </html>
                                                                                                                                                                                                                  )HTML";

                                                                                                                                                                                                                  bool setPWM(uint32_t f) {
                                                                                                                                                                                                                    uint8_t bits;

                                                                                                                                                                                                                      if (f <= 1000) bits = 12;
                                                                                                                                                                                                                        else if (f <= 10000) bits = 10;
                                                                                                                                                                                                                          else if (f <= 100000) bits = 8;
                                                                                                                                                                                                                            else if (f <= 1000000) bits = 4;
                                                                                                                                                                                                                              else bits = 1;

                                                                                                                                                                                                                                ledcDetach(PWM_PIN);

                                                                                                                                                                                                                                  if (!ledcAttach(PWM_PIN, f, bits)) {
                                                                                                                                                                                                                                      return false;
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                          pwmBits = bits;
                                                                                                                                                                                                                                            pwmFreq = f;

                                                                                                                                                                                                                                              if (pwmEnabled) {
                                                                                                                                                                                                                                                  ledcWrite(PWM_PIN, 1U << (bits - 1));
                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                        ledcWrite(PWM_PIN, 0);
                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                            return true;
                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                            void setup() {
                                                                                                                                                                                                                                                              Serial.begin(115200);

                                                                                                                                                                                                                                                                WiFi.mode(WIFI_AP);
                                                                                                                                                                                                                                                                  WiFi.softAP(ssid, password);

                                                                                                                                                                                                                                                                    setPWM(pwmFreq);

                                                                                                                                                                                                                                                                      server.on("/", []() {
                                                                                                                                                                                                                                                                          server.send(200, "text/html; charset=utf-8", page);
                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                              server.on("/set", []() {
                                                                                                                                                                                                                                                                                  if (!server.hasArg("freq")) {
                                                                                                                                                                                                                                                                                        server.send(400, "text/plain", "Missing frequency");
                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                      long f = server.arg("freq").toInt();

                                                                                                                                                                                                                                                                                                          if (f < 1 || f > 10000000) {
                                                                                                                                                                                                                                                                                                                server.send(400, "text/plain", "Invalid frequency");
                                                                                                                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                              if (!setPWM((uint32_t)f)) {
                                                                                                                                                                                                                                                                                                                                    server.send(500, "text/plain", "PWM setup failed");
                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                  server.send(200, "text/plain", "OK");
                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                      server.on("/power", []() {
                                                                                                                                                                                                                                                                                                                                                          pwmEnabled = server.arg("on") == "1";

                                                                                                                                                                                                                                                                                                                                                              if (pwmEnabled) {
                                                                                                                                                                                                                                                                                                                                                                    ledcWrite(PWM_PIN, 1U << (pwmBits - 1));
                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                              ledcWrite(PWM_PIN, 0);
                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                      server.send(200, "text/plain", "OK");
                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                          server.begin();

                                                                                                                                                                                                                                                                                                                                                                                            Serial.println("ESP32 PWM Generator started");
                                                                                                                                                                                                                                                                                                                                                                                              Serial.print("Wi-Fi: ");
                                                                                                                                                                                                                                                                                                                                                                                                Serial.println(ssid);
                                                                                                                                                                                                                                                                                                                                                                                                  Serial.println("Open: http://192.168.4.1");
                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                  void loop() {
                                                                                                                                                                                                                                                                                                                                                                                                    server.handleClient();
                                                                                                                                                                                                                                                                                                                                                                                                    }
